import{_ as e,o as l,c as i,a2 as r}from"./chunks/framework.DfDAiEgj.js";const t="/2bPM/img/taobao_SWOT.png",b=JSON.parse('{"title":"竞争分析","description":"","frontmatter":{},"headers":[],"relativePath":"knowledge/compete_analysis.md","filePath":"knowledge/compete_analysis.md","lastUpdated":null}'),o={name:"knowledge/compete_analysis.md"};function n(h,a,s,c,d,p){return l(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="竞争分析" tabindex="-1">竞争分析 <a class="header-anchor" href="#竞争分析" aria-label="Permalink to &quot;竞争分析&quot;">​</a></h1><h2 id="定义" tabindex="-1">定义 <a class="header-anchor" href="#定义" aria-label="Permalink to &quot;定义&quot;">​</a></h2><p>把市场分析放在了产品分析之后，和竞品分析并入到竞争分析。</p><h3 id="竞品思维误区" tabindex="-1">竞品思维误区 <a class="header-anchor" href="#竞品思维误区" aria-label="Permalink to &quot;竞品思维误区&quot;">​</a></h3><ol><li>你所以为的竞品，以为是领导，只是自己认为的竞品，别人根本没把你当竞品。</li><li>只把关注点集中在了那几个竞争对手上，而企业的竞争是多方面的，复杂的。</li><li>运用竞争研究资料时，自己反而会有意无意的模仿。</li></ol><h3 id="竞争思维" tabindex="-1">竞争思维 <a class="header-anchor" href="#竞争思维" aria-label="Permalink to &quot;竞争思维&quot;">​</a></h3><p>企业之间也是如此，当发生竞争的时候，彼此的利益就会发生转移，是在<strong>抢夺利益。</strong></p><p>当用竞争思维去分析时，就不会去把关注点全集中在那几个头部品牌的表面分析上，会更深入的研究竞争者和竞争局面。这才是研究竞争的真正意义。</p><p>用竞争思维去研究的时候，自然就会看那些真正跟自己形成竞争的品牌，关注竞争对手同时，也看整个大局。</p><p>所以我说是做竞争研究分析，不做竞品研究分析。<a href="https://www.zhihu.com/question/19717171" target="_blank" rel="noreferrer">5</a></p><h2 id="怎么做" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做" aria-label="Permalink to &quot;怎么做&quot;">​</a></h2><p>6个要点</p><ol><li>行业的总体竞争态势；</li><li>画竞争地图；</li><li>行业领导者梳理；</li><li>识别核心竞争者（细分出竞争能力：资金、渠道、产品技术、品牌）；</li><li>识别核心竞争者的传播策略；</li><li>识别异军突起的企业；</li></ol><h2 id="竞争战略" tabindex="-1">竞争战略 <a class="header-anchor" href="#竞争战略" aria-label="Permalink to &quot;竞争战略&quot;">​</a></h2><p>行业内：领先者、跟随者、新加入者。</p><ul><li>差异化：淘宝（C2C、性价比）、京东（B2C、配送快、购物体验好）、美丽说蘑菇街（女性电商导购到淘宝）、拼多多（拼一刀、货找人）</li><li>跟随：慧聪网跟随淘宝</li><li>成本优势：京东VS苏宁国美：偏远郊区来仓储VS闹市门店来摆卖</li><li>免费：360VS金山瑞星卡巴斯基，互联网思维：培养用户来赚钱VS软件思维：付软件。</li><li>好人/坏人：囚徒困境，好人+以牙还牙。</li></ul><h2 id="分析模型" tabindex="-1">分析模型 <a class="header-anchor" href="#分析模型" aria-label="Permalink to &quot;分析模型&quot;">​</a></h2><ul><li>定位自己 <a href="https://www.zhihu.com/pub/reader/119919151/chapter/1283860051246137344" target="_blank" rel="noreferrer">4</a>：MOST 分析模型</li><li>分析外部 <a href="https://www.zhihu.com/pub/reader/119919151/chapter/1283860051246137344" target="_blank" rel="noreferrer">4</a>：PESTLE 分析模型</li><li>自己与外部通盘考虑：SWOT分析</li></ul><h3 id="most-分析模型" tabindex="-1">MOST 分析模型 <a class="header-anchor" href="#most-分析模型" aria-label="Permalink to &quot;MOST 分析模型&quot;">​</a></h3><p>MOST 分析模型中的 4 个字母分别代表了企业的使命（Mission）、目标（Objectives）、战略（Strategies）和战术（Tactics），产品经理在做商业分析时最好能够识别这些元素，它们可以帮助公司进行初步定位，对要实现的商业目标以及如何解决使命、目标、战略和战术的执行问题进行全面分析。</p><h2 id="pestle-分析模型" tabindex="-1">PESTLE 分析模型 <a class="header-anchor" href="#pestle-分析模型" aria-label="Permalink to &quot;PESTLE 分析模型&quot;">​</a></h2><p>PESTLE 分析模型中的 6 个字母分别为 Political、Economic、Sociological、Technological、Legal 和 Environmental 的首字母，它比 PEST 分析模型多了法律和环境两个维度，使用此模型可以评估各种外部因素对公司的影响，并确定如何解决这些因素可能造成的问题。</p><h2 id="swot分析" tabindex="-1">SWOT分析 <a class="header-anchor" href="#swot分析" aria-label="Permalink to &quot;SWOT分析&quot;">​</a></h2><p>SWOT分析，又称态势分析，它是一种常用的战略规划分析模型，主要针对产品研发过程中涉及的一些关键要素进行分析。</p><p>SWOT分析是从优势（Strengths）、劣势（Weakness）、机会（Opportunity）、威胁（Threats）四个方面进行的。其中优势和劣势是针对自身而言的，即内部资源的优劣势；而机会和威胁则是针对外部而言的，可从市场、环境、社会等方面分析产品存在的机会和面临的威胁。</p><p>产品经理通过一系列调查将这些内容列举出来，并依照矩阵的形式进行排列，然后将产品设计过程中涉及的各种因素相互匹配加以分析，进而得出一系列相应的结论。记得别高估自己、低估对手！ <a href="https://weread.qq.com/web/reader/0c032c9071dbddbc0c06459k37632cd021737693cfc7149" target="_blank" rel="noreferrer">3</a></p><p>SWOT分析通常在产品规划期内使用，用以确定产品的战略方。</p><ul><li>SW分析：着眼于企业内部，由于企业是一个整体，且资源分散在各个部门或岗位之中，因此进行SW分析时必须从企业整个价值链中的每个环节入手，将涉及的每个环节与竞争对手进行对比，对比时也需要针对企业和产品进行特别分析。例如，设计一款智能音箱，需要分析企业能力，如产品部门的设计能力、研发部门的技术储备、生产制造工艺、生产能力、资金支持情况、人力资源储备、市场渠道、销售渠道等。分析产品时可以从新颖度、识别精度、制造工艺、价格优势等方面入手。</li><li>OT分析：随着社会、政治、经济、科技等方面的变化和发展，企业所处的环境也更为开放。由于这种外部环境变化是不受控制的，因此在产品分析过程中OT分析也变得至关重要。外部环境既存在威胁，也存在机会。环境威胁指的是由环境中一种不利的发展趋势所形成的不可预知的挑战，如果不采取相应的措施，这种不利趋势可能导致产品的优势被削弱。环境机会则是可能对产品形成优势的因素，通过这些机会，产品的竞争力将得到提高。</li></ul><p><img src="'+t+'" alt="淘宝SWOT6"></p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="美团-2" tabindex="-1">美团 <a href="https://www.bilibili.com/video/BV1wz4y1y7sg?p=5" target="_blank" rel="noreferrer">2</a> <a class="header-anchor" href="#美团-2" aria-label="Permalink to &quot;美团 [2]&quot;">​</a></h3><ol><li>将有限资源投放在二线城市市场，最后杀回一线</li><li>制空权：线上时o2o的入口，看出C端用户规模时关键</li><li>看重用户体验、留住用户。</li></ol>',32)])])}const m=e(o,[["render",n]]);export{b as __pageData,m as default};
